-- ============================================================
-- Opener Script: the Spanish rebuttals, as practice loops next to the
-- English ones (same 8 groups). Safe to run more than once.
-- ============================================================
set lock_timeout = '5s';

insert into public.modules (script_id, slug, title, sort_order, kind, language)
select s.id, v.slug, v.title, v.sort_order, v.kind, v.language
from public.scripts s
cross join (values
  ($t$opn-rb-stall-es$t$, $t$Objeciones: Ahora no$t$, 200, 'loop', 'es'),
  ($t$opn-rb-trust-es$t$, $t$Objeciones: Confianza$t$, 210, 'loop', 'es'),
  ($t$opn-rb-credit-es$t$, $t$Objeciones: Crédito$t$, 220, 'loop', 'es'),
  ($t$opn-rb-loan-es$t$, $t$Objeciones: El préstamo$t$, 230, 'loop', 'es'),
  ($t$opn-rb-info-es$t$, $t$Objeciones: Datos personales$t$, 240, 'loop', 'es'),
  ($t$opn-rb-others-es$t$, $t$Objeciones: Cónyuge y autorización$t$, 250, 'loop', 'es'),
  ($t$opn-rb-after-es$t$, $t$Objeciones: Después de enviar$t$, 260, 'loop', 'es'),
  ($t$opn-rb-smartcredit-es$t$, $t$Objeciones: SmartCredit$t$, 270, 'loop', 'es')
) as v(slug, title, sort_order, kind, language)
where s.slug = 'openers'
on conflict (script_id, slug) do update set title = excluded.title, sort_order = excluded.sort_order, kind = excluded.kind, language = excluded.language;

insert into public.segments
  (module_id, segment_code, sort_order, title, script_text, tones, coaching, client_should_feel, verbatim, status)
select m.id, v.code, v.sort_order, v.title, v.script_text, v.tones, nullif(v.coaching, ''), nullif(v.feel, ''), v.verbatim, 'published'
from public.modules m
join public.scripts s on s.id = m.script_id
cross join (values
($t$opn-rb-stall-es$t$, 'OPNRBES-001', 10, $t$Déjeme pensarlo$t$,
 $t$¿Qué preguntas o inquietudes tiene? (Según su respuesta, atienda la objeción correspondiente). ... Lo entiendo perfectamente. Lo bueno de nuestra compañía es que tiene mayores posibilidades de obtener una tasa de interés más baja. Además, no tiene ninguna obligación de aceptar una oferta. Estoy seguro de que podrá aclarar sus dudas. ¿Le parece bien?$t$,
 array['I CARE','AC']::text[], $t$Primero pregunte cuáles son sus preguntas o inquietudes; después, la respuesta. Termine con la confirmación.$t$, '', false),
($t$opn-rb-stall-es$t$, 'OPNRBES-002', 20, $t$Los llamaré más tarde$t$,
 $t$¿Qué preguntas o inquietudes tiene? (Según su respuesta, atienda la objeción correspondiente). ... Entiendo. Al enviar la solicitud, usted no queda comprometido a aceptar ninguna oferta. Podrá conocer distintas opciones de préstamos y decidir cuál le conviene más. Recuerde que realizamos una consulta de crédito suave (soft pull), por lo que no afectará su puntaje crediticio. ¿Le parece bien?$t$,
 array['RM']::text[], $t$Primero pregunte cuáles son sus preguntas o inquietudes.$t$, '', false),
($t$opn-rb-stall-es$t$, 'OPNRBES-003', 30, $t$No me interesa$t$,
 $t$¿Qué preguntas o inquietudes tiene? (Según su respuesta, atienda la objeción correspondiente).$t$,
 array['I CARE']::text[], $t$No acepte el no hasta saber qué hay detrás.$t$, '', false),
($t$opn-rb-stall-es$t$, 'OPNRBES-004', 40, $t$Quiero hablarlo con mi esposo o esposa$t$,
 $t$¿Qué preguntas o inquietudes tiene? (Según su respuesta, atienda la objeción correspondiente). ... Claro, no hay problema. Lo entiendo. Puedo ayudarle a completar la solicitud sin ningún compromiso ni obligación de aceptar los términos de un préstamo. Recuerde que es una consulta de crédito suave. Así podrá conocer las opciones disponibles y, cuando el especialista financiero le llame, puede incluir a su esposo o esposa en la conversación. De esa manera, ambos podrán revisar las opciones y tomar una decisión con mayor facilidad. ¿Le parece bien?$t$,
 array['RM']::text[], $t$$t$, '', false),
($t$opn-rb-stall-es$t$, 'OPNRBES-005', 50, $t$Primero quisiera investigar$t$,
 $t$¿Qué preguntas o inquietudes tiene? (Según su respuesta, atienda la objeción correspondiente). ... Claro, puede conocer más sobre nosotros en www.lionsidefinancial.com. Si desea información concreta sobre lo que podemos ofrecerle, el especialista financiero podrá ayudarle a revisar las opciones que se ajusten a sus necesidades. Además, llevamos más de siete años en el mercado. ¿Le parece bien?$t$,
 array['RM']::text[], $t$$t$, '', false),
($t$opn-rb-stall-es$t$, 'OPNRBES-006', 60, $t$Estoy muy ocupado, llámeme después$t$,
 $t$Esto toma aproximadamente tres minutos. Es un proceso muy rápido y después puedo programar una llamada del especialista financiero para el horario que más le convenga. ¿Le parece bien? ... (Si aun así no puede:) Claro, no hay problema. ¿A qué hora le conviene más que le llamemos?$t$,
 array['S','AC']::text[], $t$Transmita sentido de urgencia con el tono de voz y el ritmo.$t$, '', false),
($t$opn-rb-stall-es$t$, 'OPNRBES-007', 70, $t$Mi oferta todavía no vence$t$,
 $t$Entiendo. Sí, la oferta le da un mes para decidir. Sin embargo, las tasas de interés y los términos de los préstamos pueden cambiar de forma inesperada. Actuar ahora le permitiría adelantarse a esos cambios y evitar perder condiciones más favorables. Además, completar la solicitud toma aproximadamente cinco minutos y yo le guiaré en cada paso para facilitarle el proceso. Una vez terminada, tendrá más información para tomar una decisión. ¿Le parece bien?$t$,
 array['S']::text[], $t$$t$, '', false),
($t$opn-rb-stall-es$t$, 'OPNRBES-008', 80, $t$No me interesa porque perdí mi empleo$t$,
 $t$Lamento mucho que haya pasado por eso. El especialista financiero aún puede presentarle opciones asequibles y usted no está obligado a aceptar ninguna. Así podrá esperar y considerar una oferta cuando vuelva a tener empleo. ¿Le parece bien?$t$,
 array['I CARE']::text[], $t$$t$, '', false),
($t$opn-rb-stall-es$t$, 'OPNRBES-009', 90, $t$Ya trabajo con otra compañía o con mi banco$t$,
 $t$Claro, no hay problema. Si decide continuar con su oferta con nosotros, recuerde que cada persona que completa una solicitud es vinculada con un banco o prestamista de nuestra red. ¿Por qué no revisamos si podemos conseguirle una mejor oferta para que usted pueda compararla?$t$,
 array['RM']::text[], $t$$t$, '', false),
($t$opn-rb-trust-es$t$, 'OPNRBES-010', 10, $t$Comentarios negativos$t$,
 $t$Entiendo perfectamente su inquietud. De hecho, es una confusión que se presenta con cierta frecuencia. Hemos visto reseñas de otra compañía con un nombre parecido, pero no tenemos ninguna relación con ella. Llevamos más de siete años atendiendo a nuestros clientes y estamos comprometidos a brindarles una buena experiencia. Con gusto puedo ayudarle con su préstamo. ¿Le parece bien?$t$,
 array['CALM','AC']::text[], $t$$t$, '', false),
($t$opn-rb-trust-es$t$, 'OPNRBES-011', 20, $t$¿Cómo obtuvieron mi información?$t$,
 $t$¡Buena pregunta! Nuestro departamento de mercadeo trabaja con las agencias de información crediticia. Usted cumple con los criterios de preselección para recibir una oferta de préstamo personal y evaluar si podría beneficiarse de ella. ¿Está bien? ... (Si es necesario:) Todavía no hemos realizado una consulta de su crédito, y los montos de deuda que aparecen son estimados. Nuestro departamento de mercadeo utiliza información de preselección de Equifax para obtener un estimado de sus deudas. Con base en esa información, evaluamos si podemos ayudarle. ¿Está bien?$t$,
 array['AC']::text[], $t$$t$, '', false),
($t$opn-rb-trust-es$t$, 'OPNRBES-012', 30, $t$¿Esto es una estafa?$t$,
 $t$No, no somos una estafa. Nuestras compañías en conjunto llevan más de siete años en el mercado y con gusto puedo ayudarle. ¿Está bien? ... Entiendo perfectamente su preocupación. Puede consultar nuestra página web en www.lionsidefinancial.com. Además, todos los bancos y prestamistas con los que trabajamos deben tener una calificación A+ de Better Business Bureau (BBB). Estamos aquí para ayudarle. ¿Le parece bien?$t$,
 array['CALM','AC']::text[], $t$$t$, '', false),
($t$opn-rb-trust-es$t$, 'OPNRBES-013', 40, $t$¿Están registrados en BBB?$t$,
 $t$No, no estamos acreditados. Sin embargo, nuestras compañías en conjunto llevan más de siete años en el mercado. Además, los bancos y prestamistas con los que trabajamos figuran en BBB y cuentan con acreditación A+. ¿Le parece bien?$t$,
 array['AC']::text[], $t$$t$, '', false),
($t$opn-rb-trust-es$t$, 'OPNRBES-014', 50, $t$¿Por qué no están acreditados en BBB?$t$,
 $t$LionSide no paga por la acreditación de BBB, pero puede buscar “LionSide Financial Delaware” en Google para consultar nuestras reseñas. Para formar parte de nuestra red, un prestamista debe contar con una calificación A+ de BBB. Usted podrá verificar la información del prestamista en BBB antes de aceptar los términos del préstamo. ¿Está bien?$t$,
 array['AC']::text[], $t$$t$, '', false),
($t$opn-rb-trust-es$t$, 'OPNRBES-015', 60, $t$¿Quiénes son ustedes?$t$,
 $t$(Leer si lo preguntan durante la solicitud o al final de la llamada.) ¡Buena pregunta! Somos una red que conecta a los clientes con prestamistas y ofrece acceso a distintas opciones de préstamos. Nuestra red incluye más de veinte bancos y prestamistas, y cada uno debe contar con una calificación A+ de BBB. Trabajamos con compañías como LendingClub, Avant y Springleaf, entre otras. Cuando el especialista financiero le llame para presentarle las opciones de préstamo, también le dará toda la información sobre el prestamista. ¿Le parece bien?$t$,
 array['AC']::text[], $t$Al inicio de la llamada, repase la primera parte del guion en su lugar.$t$, '', false),
($t$opn-rb-trust-es$t$, 'OPNRBES-016', 70, $t$¿Cuánto tiempo llevan en el mercado?$t$,
